import{_ as t,o as a,c as i,ag as n}from"./chunks/framework.B3IQijK_.js";const u=JSON.parse('{"title":"Your first strategy","description":"Run one trading idea through research, Strategy Lab, paper trading, monitoring, and review.","frontmatter":{"title":"Your first strategy","description":"Run one trading idea through research, Strategy Lab, paper trading, monitoring, and review.","outline":2,"head":[["link",{"rel":"canonical","href":"https://tradecli.in/wiki/trading-office/quickstart"}]]},"headers":[],"relativePath":"trading-office/quickstart.md","filePath":"trading-office/quickstart.md"}'),s={name:"trading-office/quickstart.md"};function o(r,e,d,p,l,h){return a(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="your-first-strategy" tabindex="-1">Your first strategy <a class="header-anchor" href="#your-first-strategy" aria-label="Permalink to &quot;Your first strategy&quot;">​</a></h1><p>This walkthrough shows the complete Trading Office path using one example idea. The experiment can finish as promising, rejected, or inconclusive. That verdict is part of the tutorial: a strategy advances to paper trading only when the recorded evidence passes the machine gate.</p><h2 id="before-you-begin" tabindex="-1">Before you begin <a class="header-anchor" href="#before-you-begin" aria-label="Permalink to &quot;Before you begin&quot;">​</a></h2><p>Complete this checklist:</p><ul><li>Run <code>tradecli setup</code> and <code>tradecli doctor</code>.</li><li>Choose <strong>Hedge Fund</strong>, the current interface name for Trading Office.</li><li>Select a trading book and open an employee pane.</li><li>Use <strong>Guided</strong> mode for this walkthrough.</li><li><a href="/trading-sandbox-website-preview/wiki/getting-started/tradingview-setup">Connect TradingView</a> and keep TradingView Desktop open.</li></ul><p>Ask the employee to confirm the chart connection:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Check the TradingView connection. If it is not connected, launch TradingView</span></span>
<span class="line"><span>without closing an existing instance. Then tell me which symbol and timeframe</span></span>
<span class="line"><span>are open.</span></span></code></pre></div><p>Guided mode keeps scheduled employee workflows deferred. Once an approved backtest starts, deterministic chunk continuation can still advance it in either Guided or Autonomous · Paper trading mode.</p><h2 id="what-this-walkthrough-creates" tabindex="-1">What this walkthrough creates <a class="header-anchor" href="#what-this-walkthrough-creates" aria-label="Permalink to &quot;What this walkthrough creates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Record created</th></tr></thead><tbody><tr><td>Research</td><td>Original idea and shaped hypothesis</td></tr><tr><td>Test</td><td>Approved experiment plan, saved chunks, results, and machine verdict</td></tr><tr><td>Promote</td><td>Frozen strategy version and proposed paper deployment, only after a promising verdict</td></tr><tr><td>Paper trade</td><td>Version-tagged simulated transaction with recorded risk and exits</td></tr><tr><td>Monitor</td><td>Position marks, planned exits, and later version behavior</td></tr><tr><td>Review</td><td>Keep, Pause, Retire, or Improve decision</td></tr></tbody></table><h2 id="_1-capture-an-idea" tabindex="-1">1. Capture an idea <a class="header-anchor" href="#_1-capture-an-idea" aria-label="Permalink to &quot;1. Capture an idea&quot;">​</a></h2><p>Run:</p><p class="doc-code-label">Command</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/ideas</span></span></code></pre></div><p>Choose <strong>Capture</strong>. You can use this example or substitute your own observation:</p><p class="doc-code-label">Example</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>On RELIANCE daily bars, a close above the previous 20-day high may continue</span></span>
<span class="line"><span>higher over the next five sessions.</span></span></code></pre></div><p>Save it and choose <strong>Shape with me</strong>.</p><p><strong>Ready to continue when:</strong> the idea appears in the active book&#39;s backlog and the shaping conversation has started.</p><h2 id="_2-shape-the-test" tabindex="-1">2. Shape the test <a class="header-anchor" href="#_2-shape-the-test" aria-label="Permalink to &quot;2. Shape the test&quot;">​</a></h2><p>Answer the focused shaping questions without adding unrelated rules. For the example above, keep the intended test explicit:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Entry: daily close above the previous lookback high</span></span>
<span class="line"><span>Exit: five bars after entry, with a 2% protective stop</span></span>
<span class="line"><span>Sweep: lookback length of 10, 20, and 40 bars</span></span>
<span class="line"><span>Scope: NSE:RELIANCE on the daily timeframe</span></span>
<span class="line"><span>Falsified if: later validation is too thin or does not retain acceptable results after costs</span></span></code></pre></div><p>The shaped idea stores the claim, entry, exit, sweep candidates, scope, and falsification rule together. Choose <strong>Send to Lab</strong> when those fields describe the question you intend to test.</p><p><strong>Ready to continue when:</strong> the Idea Backlog links the idea to a Strategy Lab experiment.</p><h2 id="_3-build-and-approve-the-experiment" tabindex="-1">3. Build and approve the experiment <a class="header-anchor" href="#_3-build-and-approve-the-experiment" aria-label="Permalink to &quot;3. Build and approve the experiment&quot;">​</a></h2><p>The current <code>/backtest</code> menu is labeled <strong>Backtest Lab</strong>. It exposes the Strategy Lab contract:</p><p class="doc-code-label">Strategy Lab lifecycle</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BUILD → PLAN → RUN → JUDGE → PROMOTE</span></span></code></pre></div><p>During BUILD, tradecli restores a matching saved strategy or authors a Pine strategy, compiles it on TradingView, checks its declared inputs, and fingerprints the compiled result. The first build can require one manual <strong>Add to chart</strong> action in TradingView before verification finishes.</p><p>PLAN then shows the stored experiment specification. For this example, confirm that it contains the intended:</p><ul><li>hypothesis;</li><li><code>NSE:RELIANCE</code> symbol and daily timeframe;</li><li>fixed exit and stop rules;</li><li>10, 20, and 40-bar lookback sweep;</li><li>historical range and validation method;</li><li>commission and slippage assumptions;</li><li>ranking rule, minimum trade count, grid size, chunk count, and warnings.</li></ul><p>Approve only when the card matches the intended test. Approval starts that exact stored plan. Changing any field requires a new plan and another approval.</p><p><strong>Ready to continue when:</strong> the plan is approved and RUN has a saved job identifier.</p><h2 id="_4-let-the-saved-job-finish" tabindex="-1">4. Let the saved job finish <a class="header-anchor" href="#_4-let-the-saved-job-finish" aria-label="Permalink to &quot;4. Let the saved job finish&quot;">​</a></h2><p>Strategy Lab divides the experiment into persisted chunks. Completed chunks survive later sessions and model timeouts.</p><p>Open <strong>Backtest Lab → Jobs</strong>:</p><ul><li><strong>Status</strong> reads the saved stage and progress.</li><li><strong>Results</strong> reads the specification, leaderboard, validation, and verdict.</li><li><strong>Interpret</strong> asks AI to explain the stored result.</li><li><strong>Cancel</strong> stops the job while keeping its completed chunks.</li></ul><p>If TradingView disconnects temporarily, keep the existing job. The workflow retries with backoff. Check <strong>Status</strong> instead of creating a duplicate experiment.</p><p><strong>Ready to continue when:</strong> JUDGE records one terminal verdict—<strong>promising</strong>, <strong>rejected</strong>, or <strong>inconclusive</strong>.</p><h2 id="_5-follow-the-verdict" tabindex="-1">5. Follow the verdict <a class="header-anchor" href="#_5-follow-the-verdict" aria-label="Permalink to &quot;5. Follow the verdict&quot;">​</a></h2><p>The machine verdict controls the next step:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>What to do</th></tr></thead><tbody><tr><td><strong>Promising</strong></td><td>Continue to promotion below</td></tr><tr><td><strong>Rejected</strong></td><td>Keep the result as evidence; do not promote it</td></tr><tr><td><strong>Inconclusive</strong></td><td>Inspect the recorded reason; create a new hypothesis or plan only when the question genuinely changes</td></tr></tbody></table><p>Do not adjust thresholds merely to force the example through the gate. A rejected or inconclusive example has still completed a valid research-and-test workflow.</p><h2 id="_6-promote-a-promising-result" tabindex="-1">6. Promote a promising result <a class="header-anchor" href="#_6-promote-a-promising-result" aria-label="Permalink to &quot;6. Promote a promising result&quot;">​</a></h2><p>Only continue when the job&#39;s verdict is <strong>promising</strong>. Ask the Trading Office employee to promote the completed job.</p><p>Promotion freezes the Pine implementation, selected parameters, exit rules, universe, fingerprint, lineage, and evidence links into a strategy version. It also creates a proposed paper deployment with risk limits.</p><p>Open <strong>Backtest Lab → Approvals</strong>. Review the version, hypothesis, verdict, parameters, exits, universe, evidence job, and risk limits before approving or rejecting the paper deployment.</p><p>Approval records who authorized paper use. It does not start an automatic strategy-version execution runtime.</p><p><strong>Ready to continue when:</strong> <code>/strategies</code> shows the frozen version and its approved paper deployment.</p><h2 id="_7-create-the-current-paper-ticket" tabindex="-1">7. Create the current paper ticket <a class="header-anchor" href="#_7-create-the-current-paper-ticket" aria-label="Permalink to &quot;7. Create the current paper ticket&quot;">​</a></h2><p>Run:</p><p class="doc-code-label">Command</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/strategies</span></span></code></pre></div><p>Select the approved version and choose <strong>Trade</strong> when it is available. The current path creates a risk-sized ticket from the stored universe, exit fields, and deployment risk limit.</p><p>Review the symbol, side, instrument, quantity, stop, targets, paper fill, and total risk. Confirming the ticket records a simulated transaction in the trading book; it does not place a broker order.</p><p>The transaction carries the strategy-version and deployment identifiers into the ledger and journal.</p><p><strong>Ready to continue when:</strong> Market Terminal shows the Office paper position with its entry and exit plan.</p><h2 id="_8-monitor-and-review" tabindex="-1">8. Monitor and review <a class="header-anchor" href="#_8-monitor-and-review" aria-label="Permalink to &quot;8. Monitor and review&quot;">​</a></h2><p>Open Market Terminal:</p><p class="doc-code-label">Command</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/terminal</span></span></code></pre></div><p>Use it to inspect the position, current mark, unrealized P&amp;L, remaining quantity, and recorded exit plan. The position monitor checks stored stops, targets, time exits, and applicable intraday cutoffs. A watch is separate: use one when an employee should revisit the wider thesis or report a material contextual change.</p><p>Return to <code>/strategies</code> for version-specific evidence:</p><ul><li><strong>Journal</strong> — tagged trades and their computed outcomes.</li><li><strong>Forward check</strong> — the unchanged version over post-promotion history.</li><li><strong>Review</strong> — original expectation beside the paper journal.</li><li><strong>Reviews</strong> — earlier decisions and child hypotheses.</li></ul><p>Review warns when there are fewer than ten closed paper trades. You can inspect the flow with a thin sample, but treat any decision conservatively.</p><p>Choose one recorded outcome when the evidence supports it:</p><ul><li><strong>Keep</strong> — continue the version as-is.</li><li><strong>Pause</strong> — stop new entries for an applicable deployment.</li><li><strong>Retire</strong> — permanently stop the version.</li><li><strong>Improve</strong> — create a child draft around one explicit change hypothesis.</li></ul><p>An improved child returns to Strategy Lab and must earn its own verdict. The parent version and its evidence remain unchanged.</p><h2 id="completion-check" tabindex="-1">Completion check <a class="header-anchor" href="#completion-check" aria-label="Permalink to &quot;Completion check&quot;">​</a></h2><p>If the experiment was promising and you completed the paper path, the local Trading Office record now connects:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idea → approved plan → saved job → machine verdict → frozen version</span></span>
<span class="line"><span>     → deployment decision → paper activity → journal → review</span></span></code></pre></div><p>If the experiment was rejected or inconclusive, the record correctly ends at the verdict. That is not an incomplete run; it is a strategy that did not pass the promotion gate.</p><h2 id="continue-through-the-lifecycle" tabindex="-1">Continue through the lifecycle <a class="header-anchor" href="#continue-through-the-lifecycle" aria-label="Permalink to &quot;Continue through the lifecycle&quot;">​</a></h2><ul><li>Shape stronger hypotheses → <a href="./ideas">Research and ideas</a></li><li>Understand the evidence pipeline → <a href="./strategy-lab">Test in Strategy Lab</a></li><li>Configure repeated observation → <a href="./watches">Automation tools</a></li><li>Compare paper behavior with the test → <a href="./review">Review and improve</a></li></ul>`,74)])])}const g=t(s,[["render",o]]);export{u as __pageData,g as default};
